(window.AZ = window.AZ || { worlds: [] }).worlds.push({
  id: 'w3', order: 3,
  title: 'Administración y gobernanza', weight: '30-35 %', share: 0.325,
  levels: [
  // ───────────────────────────── w3l1 ─────────────────────────────
  { id: 'w3l1', title: 'Administración de costos', minutes: 7,
    goal: 'Identificar qué hace subir o bajar la factura de Azure y qué herramienta usar para estimar, vigilar y repartir el gasto.',
    lesson: [
      { type: 'text', title: 'La nube cobra por lo que usas… y por lo que olvidas',
        body: 'En Azure pagas según el **modelo de consumo** (OpEx): sin compra de servidores, pero cada recurso encendido, cada GB almacenado y cada dato que sale de Azure suma. Aprobar este tema es saber **qué mueve el precio**, cómo **estimarlo antes** y cómo **controlarlo después**.' },
      { type: 'analogy',
        body: 'Azure es como un **taxi con taxímetro**: el precio depende del tipo de auto (tipo de recurso), cuánto tiempo lo usas (consumo), la ciudad (región) y si te llevas equipaje fuera del país (tráfico saliente). Si lo dejas esperando en la puerta con el motor encendido (recursos huérfanos), el taxímetro sigue corriendo.' },
      { type: 'cards', title: 'Factores que afectan el costo',
        items: [
          { title: 'Tipo de recurso y consumo', body: 'Cada servicio tiene su medidor: tamaño de VM, nivel de almacenamiento, horas encendidas, transacciones. Más capacidad o más tiempo = más costo.' },
          { title: 'Mantenimiento y huérfanos', body: 'Al borrar una VM pueden quedar **discos, IP públicas o NIC** que siguen cobrando. Revisa y limpia recursos sin uso.' },
          { title: 'Región', body: 'El mismo servicio puede costar distinto según la región, por costos locales de energía, impuestos o mano de obra.' },
          { title: 'Ancho de banda', body: 'La **entrada** de datos (ingress) suele ser gratis. La **salida** (egress) y la transferencia entre regiones se cobran según la **zona de facturación**.' },
          { title: 'Reservas y Azure Hybrid Benefit', body: '**Instancias reservadas**: compromiso de 1 o 3 años con gran descuento. **Azure Hybrid Benefit**: reutiliza licencias Windows Server/SQL Server con Software Assurance.' },
          { title: 'Azure Marketplace', body: 'Las soluciones de terceros cobran el software del proveedor **más** los recursos de Azure que consumen, todo en tu factura de Azure.' }
        ] },
      { type: 'sort', title: '¿Esta decisión sube o baja la factura?', buckets: ['Aumenta el costo', 'Reduce el costo'],
        items: [
          { text: 'Dejar discos de VMs eliminadas sin borrar', bucket: 0 },
          { text: 'Reservar una VM 24/7 por 3 años', bucket: 1 },
          { text: 'Descargar terabytes desde Azure a tu oficina', bucket: 0 },
          { text: 'Usar licencias de Windows Server con Software Assurance', bucket: 1 },
          { text: 'Apagar y desasignar VMs de prueba por la noche', bucket: 1 },
          { text: 'Elegir un tamaño de VM mucho mayor al necesario', bucket: 0 }
        ] },
      { type: 'trap',
        body: '“Todo tráfico de red se cobra” es **falso**: la entrada de datos a Azure normalmente es **gratis**. Lo que se paga es la **salida** y la transferencia entre regiones/zonas de facturación. Otra trampa: los **grupos de recursos** no cuestan nada; pagas los recursos que contienen.' },
      { type: 'compare', title: 'Dos calculadoras, dos preguntas',
        head: ['', 'Calculadora de precios', 'Calculadora de TCO'],
        rows: [
          ['Pregunta', '¿Cuánto costará lo que voy a desplegar?', '¿Cuánto ahorro moviendo mi CPD a Azure?'],
          ['Entrada', 'Servicios, región, nivel, horas', 'Servidores, BD, almacenamiento y red locales'],
          ['Resultado', 'Estimación mensual por servicio', 'Comparación local vs Azure a varios años'],
          ['Temario actual', 'Mencionada explícitamente', 'Útil conocerla como contraste']
        ] },
      { type: 'flip', title: 'Microsoft Cost Management',
        items: [
          { front: 'Análisis de costos', back: 'Explora el gasto real y previsto, filtrado por servicio, grupo de recursos, región o **etiqueta**.' },
          { front: 'Presupuesto', back: 'Límite de gasto para un ámbito y período. Al llegar a umbrales **notifica** (y puede disparar un grupo de acciones); no apaga nada por sí solo.' },
          { front: 'Alerta de presupuesto', back: 'Se activa cuando el gasto real o previsto alcanza un umbral del presupuesto.' },
          { front: 'Alerta de crédito', back: 'Avisa cuando se consume el crédito o compromiso monetario de un contrato (p. ej., Enterprise Agreement).' },
          { front: 'Alerta de cuota del departamento', back: 'Avisa cuando un departamento alcanza el umbral de cuota de gasto que tiene asignado.' }
        ] },
      { type: 'text', title: 'Etiquetas: las pegatinas del gasto',
        body: 'Una **etiqueta** es un par **nombre-valor** (`CentroCosto: Ventas`, `Entorno: Prod`) que agregas a suscripciones, grupos de recursos o recursos. Sirven para **agrupar costos**, organizar, automatizar y gestionar operaciones. No cambian el comportamiento del recurso ni dan permisos.' },
      { type: 'trap',
        body: 'Las etiquetas **NO se heredan por defecto**: etiquetar un grupo de recursos no etiqueta los recursos que contiene. Si el examen pide “asegurar que todos los recursos tengan la etiqueta X” o “heredar la etiqueta del grupo”, la respuesta es **Azure Policy**.' },
      { type: 'check', q: 'Tu equipo quiere saber cuánto gastará al mes una nueva aplicación con 3 VMs y una base de datos antes de desplegarla. ¿Qué usas?',
        o: ['Análisis de costos', 'Calculadora de precios', 'Azure Advisor'], a: 1,
        why: 'La calculadora de precios estima el costo de servicios que aún no existen. Análisis de costos y Advisor trabajan sobre lo que ya está desplegado.' },
      { type: 'keypoints', items: [
        'Costo = tipo de recurso + consumo + región + tráfico saliente + recursos olvidados.',
        'Entrada de datos gratis; salida y transferencia entre regiones se cobran.',
        'Instancias reservadas y Azure Hybrid Benefit reducen costos de cargas estables.',
        'Calculadora de precios = estimar antes; Cost Management = analizar, presupuestar y alertar después.',
        'Etiquetas: pares nombre-valor, no se heredan; se exigen o heredan con Azure Policy.'
      ] }
    ],
    questions: [
      { t: 'single', q: 'Una empresa elimina una máquina virtual de pruebas, pero la factura del mes siguiente sigue mostrando cargos relacionados. ¿Cuál es la causa más probable?',
        o: ['Azure cobra la VM durante 30 días después de eliminarla', 'Quedaron recursos asociados, como discos administrados o una IP pública, sin eliminar', 'El grupo de recursos vacío genera un cargo mensual', 'Las etiquetas de la VM siguen facturándose'], a: 1,
        why: 'Al borrar una VM, sus discos, IP públicas o NIC pueden quedar como recursos huérfanos que siguen cobrando. Los grupos de recursos y las etiquetas son gratuitos, y Azure no cobra una VM ya eliminada.', d: 1 },
      { t: 'single', q: '¿Qué tipo de transferencia de datos normalmente NO genera cargos en Azure?',
        o: ['Datos que salen de Azure hacia Internet', 'Datos que se transfieren entre regiones de distintos continentes', 'Datos de salida desde una VM hacia la red local', 'Datos que entran a los centros de datos de Azure'], a: 3,
        why: 'La entrada de datos (ingress) es generalmente gratuita. La salida a Internet o a la red local y la transferencia entre regiones se cobran según la zona de facturación.', d: 1 },
      { t: 'single', q: 'Un arquitecto debe presentar al director financiero el costo mensual estimado de una solución que todavía no existe: dos VMs, una cuenta de almacenamiento y Azure SQL Database. ¿Qué herramienta debe usar?',
        o: ['Calculadora de precios de Azure', 'Análisis de costos de Microsoft Cost Management', 'Azure Advisor', 'Azure Service Health'], a: 0,
        why: 'La calculadora de precios estima el costo de servicios que planeas desplegar. Análisis de costos y Advisor trabajan sobre recursos existentes, y Service Health informa de incidencias.', d: 1 },
      { t: 'single', q: 'Una empresa quiere comparar lo que le cuesta mantener su centro de datos propio durante varios años frente a ejecutar esas cargas en Azure. ¿Qué herramienta encaja mejor con esa pregunta?',
        o: ['Calculadora de precios', 'Azure Advisor', 'Calculadora de costo total de propiedad (TCO)', 'Presupuestos de Cost Management'], a: 2,
        why: 'La calculadora de TCO compara el costo de infraestructura local con Azure a lo largo del tiempo. La calculadora de precios solo estima servicios de Azure, y presupuestos o Advisor actúan sobre gasto ya existente.', d: 2 },
      { t: 'single', q: 'Una organización tiene licencias de Windows Server con Software Assurance y quiere usarlas para pagar menos por sus VMs en Azure. ¿Qué debe aplicar?',
        o: ['Instancias reservadas de Azure', 'Azure Hybrid Benefit', 'Azure Marketplace', 'Una etiqueta de licencia en cada VM'], a: 1,
        why: 'Azure Hybrid Benefit permite reutilizar licencias locales de Windows Server y SQL Server con Software Assurance. Las reservas son un compromiso de uso, no de licencias, y una etiqueta no cambia el precio.', d: 1 },
      { t: 'single', q: 'Una carga de trabajo funciona 24 horas al día, todos los días, y se mantendrá al menos tres años con el mismo tamaño de VM. ¿Qué opción ofrece el mayor ahorro sobre el precio de pago por uso?',
        o: ['Cambiar a una región con más zonas de disponibilidad', 'Crear un presupuesto mensual', 'Agregar etiquetas de centro de costo', 'Comprar una instancia reservada a 3 años'], a: 3,
        why: 'Las instancias reservadas dan un descuento importante a cambio de un compromiso de 1 o 3 años, ideal para cargas estables. Presupuestos y etiquetas ayudan a controlar, pero no reducen el precio unitario.', d: 2 },
      { t: 'single', q: '¿Qué funcionalidad de Microsoft Cost Management permite ver en qué servicios, grupos de recursos o etiquetas se ha gastado el dinero este mes?',
        o: ['Análisis de costos', 'Calculadora de precios', 'Alertas de crédito', 'Azure Resource Manager'], a: 0,
        why: 'Análisis de costos muestra el gasto real y previsto con filtros y agrupaciones. La calculadora de precios estima antes de desplegar y las alertas de crédito solo avisan de consumo de crédito.', d: 1 },
      { t: 'single', q: 'Se configura un presupuesto de 1 000 USD con una alerta al 90 %. El gasto llega a 950 USD. ¿Qué ocurre por defecto?',
        o: ['Azure detiene todas las VMs de la suscripción', 'La suscripción se deshabilita hasta el próximo mes', 'Se envía una notificación a los destinatarios configurados', 'Los recursos se convierten en solo lectura'], a: 2,
        why: 'Un presupuesto solo notifica al alcanzar sus umbrales. No detiene recursos por sí mismo; para automatizar acciones habría que asociar un grupo de acciones, por ejemplo con un runbook o una Logic App.', d: 2 },
      { t: 'single', q: 'Finanzas necesita repartir el gasto de Azure entre los departamentos de Marketing y Ventas, cuyos recursos están mezclados en varios grupos de recursos. ¿Qué es lo más adecuado?',
        o: ['Crear una suscripción nueva por cada recurso', 'Aplicar etiquetas como Departamento: Marketing y filtrar por ellas en análisis de costos', 'Aplicar bloqueos de solo lectura por departamento', 'Mover todos los recursos a la misma región'], a: 1,
        why: 'Las etiquetas permiten agrupar costos de forma transversal a grupos de recursos y suscripciones. Los bloqueos no organizan costos, y crear una suscripción por recurso es inmanejable.', d: 2 },
      { t: 'single', q: 'El grupo de recursos RG-Ventas tiene la etiqueta Entorno: Producción. Un administrador crea una VM nueva dentro de RG-Ventas sin políticas configuradas. ¿Qué etiquetas tendrá la VM?',
        o: ['Ninguna, porque las etiquetas no se heredan por defecto', 'Entorno: Producción, heredada automáticamente', 'Las etiquetas de la suscripción', 'Entorno: Producción, pero solo visible en Cost Management'], a: 0,
        why: 'Las etiquetas no se heredan del grupo de recursos ni de la suscripción por defecto. Para heredarlas o exigirlas automáticamente se usa Azure Policy.', d: 2 },
      { t: 'single', q: 'Una empresa quiere que sea imposible crear recursos sin la etiqueta CentroCosto. ¿Qué servicio debe usar?',
        o: ['Microsoft Cost Management', 'Azure Advisor', 'Bloqueos de recursos', 'Azure Policy'], a: 3,
        why: 'Azure Policy puede denegar la creación de recursos sin cierta etiqueta, o agregarla o heredarla. Cost Management solo analiza costos, Advisor recomienda y los bloqueos impiden borrar o modificar.', d: 1 },
      { t: 'single', q: 'El mismo tamaño de VM cuesta distinto en la región Sur de Brasil que en Este de EE. UU. ¿Qué factor explica la diferencia?',
        o: ['El número de etiquetas aplicadas', 'La región, que tiene costos locales distintos', 'El tipo de cuenta de Microsoft Entra ID', 'La cantidad de grupos de recursos de la suscripción'], a: 1,
        why: 'Los precios varían por región según costos locales como energía, impuestos o infraestructura. Etiquetas, grupos de recursos y el tipo de cuenta de Entra ID no afectan el precio de la VM.', d: 1 },
      { t: 'single', q: 'Una organización con un contrato Enterprise Agreement quiere saber cuándo se ha consumido gran parte de su compromiso monetario prepagado. ¿Qué tipo de alerta de Cost Management corresponde?',
        o: ['Alerta de presupuesto', 'Alerta de métrica de Azure Monitor', 'Alerta de crédito', 'Alerta de Resource Health'], a: 2,
        why: 'Las alertas de crédito avisan del consumo del crédito o compromiso monetario. Las de presupuesto dependen de un presupuesto que tú defines, y las de Monitor o Resource Health no tratan dinero.', d: 3 },
      { t: 'multi', q: 'Una VM ejecuta SQL Server sin interrupción y seguirá así varios años. La empresa ya tiene licencias de SQL Server con Software Assurance. ¿Qué dos acciones reducen su costo? Selecciona dos.',
        o: ['Comprar una instancia reservada', 'Agregar etiquetas de centro de costo', 'Aplicar Azure Hybrid Benefit', 'Moverla a un grupo de recursos nuevo', 'Configurar una alerta de presupuesto'], a: [0, 2],
        why: 'Las reservas descuentan cargas estables y Azure Hybrid Benefit reutiliza licencias existentes. Etiquetas, grupos de recursos y alertas ayudan a organizar o vigilar, pero no bajan el precio.', d: 2 },
      { t: 'multi', q: '¿Qué tipos de alertas ofrece Microsoft Cost Management? Selecciona dos.',
        o: ['Alertas de Resource Health', 'Alertas de presupuesto', 'Alertas de uso de CPU', 'Alertas de cuota del departamento', 'Alertas de Azure Status'], a: [1, 3],
        why: 'Cost Management ofrece alertas de presupuesto, de crédito y de cuota del departamento. CPU y Resource Health pertenecen a Azure Monitor y Service Health, y Azure Status es una página pública.', d: 2 },
      { t: 'multi', q: '¿Qué factores influyen directamente en el costo de una solución en Azure? Selecciona tres.',
        o: ['La región donde se despliega', 'El número de grupos de recursos', 'El tipo y tamaño del recurso', 'La cantidad de etiquetas', 'El tráfico de datos de salida'], a: [0, 2, 4],
        why: 'Región, tipo/tamaño del recurso y tráfico saliente cambian la factura. Los grupos de recursos y las etiquetas son gratuitos y solo sirven para organizar.', d: 2 },
      { t: 'multi', q: '¿Para qué sirven las etiquetas de recursos? Selecciona dos.',
        o: ['Agrupar y reportar costos por centro de costo o proyecto', 'Impedir que un recurso se elimine', 'Conceder permisos a usuarios', 'Identificar recursos para automatizar tareas, como apagar VMs de desarrollo', 'Cifrar los datos de un recurso'], a: [0, 3],
        why: 'Las etiquetas organizan recursos para costos, operaciones y automatización. Impedir borrados es tarea de los bloqueos, los permisos son de RBAC y el cifrado no depende de etiquetas.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Los datos que entran a Azure normalmente no se cobran.', a: true },
          { text: 'Transferir datos entre regiones de Azure siempre es gratuito.', a: false },
          { text: 'El precio de un mismo servicio puede variar entre regiones.', a: true }
        ],
        why: 'La entrada suele ser gratis, pero la transferencia entre regiones y la salida se cobran según zonas de facturación. Los precios dependen de la región.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Una etiqueta es un par nombre-valor.', a: true },
          { text: 'Una etiqueta aplicada a un grupo de recursos se copia automáticamente a todos sus recursos.', a: false },
          { text: 'Azure Policy puede exigir que los recursos tengan determinadas etiquetas.', a: true }
        ],
        why: 'Las etiquetas son pares nombre-valor y no se heredan por defecto. Azure Policy puede exigirlas, agregarlas o heredarlas desde el grupo de recursos.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Al superar un presupuesto, Cost Management apaga automáticamente las VMs de la suscripción.', a: false },
          { text: 'Una alerta de presupuesto puede basarse en el costo real o en el costo previsto.', a: true },
          { text: 'Análisis de costos permite filtrar el gasto por etiqueta.', a: true }
        ],
        why: 'Los presupuestos notifican; no detienen recursos por sí solos. Sus alertas pueden usar costo real o previsto, y análisis de costos agrupa y filtra por etiquetas.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'La calculadora de precios estima el costo de servicios de Azure que planeas desplegar.', a: true },
          { text: 'Para usar la calculadora de precios necesitas una suscripción de Azure activa.', a: false },
          { text: 'La calculadora de TCO compara costos de infraestructura local con Azure.', a: true }
        ],
        why: 'La calculadora de precios es pública y no requiere suscripción. La de TCO compara infraestructura local con Azure a lo largo del tiempo.', d: 2 },
      { t: 'drop', q: 'Para pagar menos por VMs en Azure reutilizando licencias de SQL Server con Software Assurance, se aplica ___.',
        o: ['Azure Hybrid Benefit', 'una instancia reservada', 'Azure Marketplace', 'Azure Advisor'], a: 0,
        why: 'Azure Hybrid Benefit permite usar licencias existentes con Software Assurance. Las reservas descuentan por compromiso de uso, no por licencias.', d: 1 },
      { t: 'drop', q: 'Discos o IP públicas que siguen cobrando después de eliminar la VM que los usaba son recursos ___.',
        o: ['reservados', 'etiquetados', 'huérfanos', 'bloqueados'], a: 2,
        why: 'Se llaman recursos huérfanos: ya no prestan servicio pero siguen generando costo. Limpiarlos es parte del mantenimiento de costos.', d: 1 },
      { t: 'drop', q: 'Para ver el gasto real de la suscripción agrupado por servicio, grupo de recursos o etiqueta se usa ___.',
        o: ['la calculadora de precios', 'el análisis de costos de Microsoft Cost Management', 'Azure Service Health', 'Azure Resource Manager'], a: 1,
        why: 'Análisis de costos trabaja con el gasto real y previsto. La calculadora estima antes de desplegar y Service Health informa de incidencias.', d: 1 },
      { t: 'match', q: 'Relaciona cada tipo de alerta de Cost Management con lo que la dispara.',
        pairs: [
          ['Alerta de presupuesto', 'El gasto alcanza un umbral del presupuesto definido'],
          ['Alerta de crédito', 'Se consume el crédito o compromiso monetario del contrato'],
          ['Alerta de cuota del departamento', 'Un departamento alcanza el umbral de su cuota de gasto']
        ],
        why: 'Presupuesto: umbral de un presupuesto que tú creas. Crédito: consumo del compromiso monetario. Cuota del departamento: límite de gasto de un departamento.', d: 2 },
      { t: 'match', q: 'Relaciona cada necesidad con la herramienta adecuada.',
        pairs: [
          ['Estimar el costo de una solución antes de desplegarla', 'Calculadora de precios'],
          ['Comparar el costo del CPD propio con Azure', 'Calculadora de TCO'],
          ['Ver en qué se gastó el dinero el mes pasado', 'Análisis de costos'],
          ['Atribuir recursos a un centro de costo', 'Etiquetas']
        ],
        why: 'Precios estima, TCO compara local vs nube, análisis de costos revisa el gasto real y las etiquetas permiten atribuirlo por proyecto o departamento.', d: 1 }
    ] },

  // ───────────────────────────── w3l2 ─────────────────────────────
  { id: 'w3l2', title: 'Gobernanza y cumplimiento', minutes: 7,
    goal: 'Distinguir Microsoft Purview, Azure Policy, RBAC y los bloqueos de recursos, y elegir el correcto en cada escenario.',
    lesson: [
      { type: 'text', title: 'Gobernar no es vigilar: es poner reglas',
        body: 'Cuando una empresa tiene cientos de recursos y decenas de equipos, necesita reglas: **qué datos tiene y dónde** (Purview), **cómo deben ser los recursos** (Azure Policy), **quién puede hacer qué** (RBAC) y **qué no se puede tocar** (bloqueos). El examen te pondrá escenarios para elegir entre ellos.' },
      { type: 'analogy',
        body: 'Piensa en un **edificio de oficinas**. **RBAC** son las tarjetas de acceso: quién entra a qué piso. **Azure Policy** es el reglamento de construcción: no importa quién seas, no puedes pintar la fachada de rosa. Un **bloqueo** es el candado en el cuarto eléctrico: ni el dueño del edificio lo abre sin quitar primero el candado. **Purview** es el archivo central que sabe qué documentos hay en cada oficina.' },
      { type: 'cards', title: 'Microsoft Purview',
        items: [
          { title: 'Qué es', body: 'Familia de soluciones de **gobernanza de datos**, **riesgo y cumplimiento** que te da una vista unificada de tus datos.' },
          { title: 'Dónde mira', body: 'Datos **locales**, **multinube** (por ejemplo AWS) y **SaaS** (por ejemplo Microsoft 365), no solo Azure.' },
          { title: 'Mapa de datos', body: 'Descubre y escanea orígenes, registra **metadatos**, clasifica datos sensibles y muestra su **linaje** (de dónde vienen y adónde van).' },
          { title: 'Riesgo y cumplimiento', body: 'Protege y gobierna información sensible: protección de información, prevención de pérdida de datos, auditoría y gestión del cumplimiento.' }
        ] },
      { type: 'flip', title: 'Vocabulario de Azure Policy',
        items: [
          { front: 'Definición de directiva', back: 'Una regla: condición + **efecto** (por ejemplo, “solo regiones de Europa”).' },
          { front: 'Iniciativa', back: 'Conjunto de definiciones agrupadas para un objetivo, como cumplir una norma de seguridad.' },
          { front: 'Asignación', back: 'Aplicar una definición o iniciativa a un **ámbito**: grupo de administración, suscripción o grupo de recursos.' },
          { front: 'Efectos', back: '**Deny** bloquea, **Audit** registra el incumplimiento, **Modify**/**DeployIfNotExists** corrigen o completan.' },
          { front: 'Corrección', back: 'Tarea que lleva recursos **existentes** no conformes a cumplimiento (efectos Modify o DeployIfNotExists).' }
        ] },
      { type: 'text', title: 'Herencia y evaluación',
        body: 'Una directiva asignada a un **grupo de administración** se hereda a todas sus suscripciones, grupos de recursos y recursos. Azure Policy evalúa recursos **nuevos y existentes**: los existentes que no cumplen aparecen como **no conformes** en el panel de cumplimiento, pero **no se eliminan**.' },
      { type: 'text', title: 'Bloqueos de recursos',
        body: 'Dos tipos: **Eliminar** (`CanNotDelete`): puedes leer y modificar, pero no borrar. **Solo lectura** (`ReadOnly`): solo leer; ni modificar ni borrar. Se aplican a suscripción, grupo de recursos o recurso, y se **heredan** hacia abajo.' },
      { type: 'trap',
        body: 'Los bloqueos aplican a **todos**, **incluido el Propietario**. Un Propietario no puede borrar un recurso bloqueado: primero debe **quitar el bloqueo** (para lo cual necesita permisos sobre `Microsoft.Authorization/locks`) y luego eliminar. Ser Propietario no “salta” el candado.' },
      { type: 'compare', title: 'Policy vs RBAC vs bloqueos',
        head: ['', 'Azure Policy', 'RBAC', 'Bloqueos'],
        rows: [
          ['Pregunta', '¿Cómo deben ser los recursos?', '¿Quién puede hacer qué?', '¿Se puede borrar o cambiar?'],
          ['Se centra en', 'Propiedades del recurso', 'Acciones de usuarios e identidades', 'Proteger recursos concretos'],
          ['Ejemplo', 'Solo VMs de ciertos tamaños', 'Soporte puede reiniciar VMs', 'No borrar la BD de producción'],
          ['Afecta al Propietario', 'Sí', 'Define sus permisos', 'Sí']
        ] },
      { type: 'sort', title: '¿Qué herramienta resuelve cada necesidad?', buckets: ['Azure Policy', 'RBAC', 'Bloqueo', 'Purview'],
        items: [
          { text: 'Prohibir recursos fuera de Europa', bucket: 0 },
          { text: 'Dar a un auditor acceso de solo lectura a una suscripción', bucket: 1 },
          { text: 'Evitar que alguien borre por error el almacén de claves', bucket: 2 },
          { text: 'Clasificar datos personales en SQL local y Amazon S3', bucket: 3 },
          { text: 'Exigir una etiqueta en todos los recursos', bucket: 0 },
          { text: 'Permitir a un desarrollador administrar solo un grupo de recursos', bucket: 1 }
        ] },
      { type: 'check', q: 'Una directiva con efecto Deny se asigna a una suscripción que ya tiene recursos que la incumplen. ¿Qué pasa con ellos?',
        o: ['Se eliminan automáticamente', 'Se marcan como no conformes, pero siguen funcionando', 'Se convierten en solo lectura'], a: 1,
        why: 'Azure Policy evalúa los existentes y los reporta como no conformes; Deny solo impide crear o actualizar recursos que no cumplan. Nunca borra recursos.' },
      { type: 'keypoints', items: [
        'Purview: gobernanza de datos, riesgo y cumplimiento en local, multinube y SaaS.',
        'Azure Policy controla cómo son los recursos; RBAC, quién hace qué; bloqueos, qué no se toca.',
        'Iniciativa = grupo de definiciones de directiva.',
        'Policy y bloqueos se heredan desde el ámbito donde se aplican.',
        'Bloqueos Eliminar y Solo lectura aplican incluso al Propietario: hay que quitarlos primero.'
      ] }
    ],
    questions: [
      { t: 'single', q: 'Una empresa tiene datos en SQL Server local, en Amazon S3 y en Azure Data Lake. Necesita descubrirlos, clasificar los datos sensibles y ver su linaje desde un único lugar. ¿Qué solución debe usar?',
        o: ['Azure Policy', 'Microsoft Purview', 'Azure Arc', 'Microsoft Cost Management'], a: 1,
        why: 'Microsoft Purview ofrece gobernanza de datos unificada en local, multinube y SaaS, con mapa de datos, clasificación y linaje. Policy rige recursos, Arc los administra fuera de Azure y Cost Management trata gastos.', d: 1 },
      { t: 'single', q: 'Por motivos regulatorios, una organización solo puede crear recursos en regiones de la Unión Europea. ¿Cómo lo garantiza?',
        o: ['Asignando un rol RBAC de Lector a todos los usuarios', 'Aplicando un bloqueo de solo lectura a la suscripción', 'Asignando una directiva de Azure Policy de ubicaciones permitidas', 'Configurando una alerta de presupuesto'], a: 2,
        why: 'Azure Policy puede denegar la creación de recursos fuera de las ubicaciones permitidas. RBAC limita acciones de usuarios, pero no propiedades como la región, y un bloqueo de solo lectura impediría crear cualquier cosa.', d: 1 },
      { t: 'single', q: 'Un equipo necesita seguir actualizando la configuración de la base de datos de producción, pero quiere evitar que alguien la elimine por accidente. ¿Qué debe aplicar?',
        o: ['Un bloqueo de solo lectura (ReadOnly)', 'Una iniciativa de Azure Policy', 'Una etiqueta Entorno: Producción', 'Un bloqueo Eliminar (CanNotDelete)'], a: 3,
        why: 'El bloqueo Eliminar permite leer y modificar, pero impide borrar. Solo lectura bloquearía también los cambios, y una etiqueta no protege nada.', d: 1 },
      { t: 'single', q: 'Un usuario con rol Propietario intenta eliminar un grupo de recursos que tiene un bloqueo Eliminar. ¿Qué ocurre?',
        o: ['La eliminación falla; primero debe quitar el bloqueo', 'Se elimina, porque el Propietario ignora los bloqueos', 'Se eliminan los recursos, pero no el grupo', 'Azure pide aprobación de otro Propietario'], a: 0,
        why: 'Los bloqueos aplican a todos los usuarios y roles, incluido el Propietario. Hay que quitar el bloqueo antes de eliminar.', d: 2 },
      { t: 'single', q: 'En Azure Policy, ¿qué es una iniciativa?',
        o: ['Un rol que permite asignar directivas', 'Un conjunto de definiciones de directiva agrupadas para un objetivo común', 'Una tarea que elimina recursos no conformes', 'Un bloqueo aplicado a un grupo de administración'], a: 1,
        why: 'Una iniciativa agrupa varias definiciones, por ejemplo para cumplir una norma. No es un rol, no elimina recursos ni es un bloqueo.', d: 1 },
      { t: 'single', q: 'El equipo de soporte debe poder reiniciar máquinas virtuales, pero no crearlas ni eliminarlas. ¿Qué mecanismo controla esto?',
        o: ['Azure Policy', 'Bloqueos de recursos', 'Control de acceso basado en roles de Azure (RBAC)', 'Microsoft Purview'], a: 2,
        why: 'RBAC define qué acciones puede hacer cada usuario o grupo sobre qué ámbito. Policy controla propiedades de los recursos, no permisos de usuarios.', d: 1 },
      { t: 'single', q: 'Una directiva se asigna a un grupo de administración que contiene tres suscripciones. ¿A qué se aplica?',
        o: ['Solo a las suscripciones creadas después de la asignación', 'Solo al propio grupo de administración', 'A la primera suscripción del grupo', 'A las tres suscripciones y a todos sus grupos de recursos y recursos'], a: 3,
        why: 'Las asignaciones de Azure Policy se heredan hacia abajo: grupo de administración → suscripciones → grupos de recursos → recursos.', d: 2 },
      { t: 'single', q: 'Se asigna una directiva con efecto Deny que prohíbe cierto tamaño de VM. Ya existen dos VMs de ese tamaño. ¿Qué sucede con ellas?',
        o: ['Aparecen como no conformes, pero no se eliminan ni se detienen', 'Se redimensionan automáticamente', 'Se eliminan en la siguiente evaluación', 'Quedan bloqueadas en solo lectura'], a: 0,
        why: 'Azure Policy evalúa los recursos existentes y los reporta como no conformes. Deny solo impide crear o actualizar recursos fuera de la regla; nunca borra.', d: 2 },
      { t: 'single', q: 'Se aplica un bloqueo de solo lectura a una cuenta de almacenamiento. ¿Qué efecto tiene?',
        o: ['Los usuarios pueden modificar la configuración, pero no eliminarla', 'Solo el Propietario puede seguir modificándola', 'Los usuarios autorizados pueden leerla, pero nadie puede modificarla ni eliminarla', 'Se cifran todos los datos de la cuenta'], a: 2,
        why: 'ReadOnly impide modificar y eliminar, para todos los usuarios, incluido el Propietario. Permitir cambios pero no borrar es el bloqueo Eliminar.', d: 2 },
      { t: 'single', q: 'Seguridad quiere saber qué recursos no tienen habilitado el cifrado, pero sin bloquear todavía ningún despliegue. ¿Qué efecto de Azure Policy debe usar?',
        o: ['Deny', 'Audit', 'Un bloqueo Eliminar', 'DeployIfNotExists'], a: 1,
        why: 'Audit registra el incumplimiento sin bloquear. Deny impediría el despliegue, DeployIfNotExists despliega algo para corregir y un bloqueo no evalúa cumplimiento.', d: 2 },
      { t: 'single', q: '¿Qué componente de Microsoft Purview mantiene un inventario de los metadatos de los orígenes de datos de la organización, con su clasificación y linaje?',
        o: ['El panel de cumplimiento de Azure Policy', 'El registro de actividad', 'Azure Resource Manager', 'El mapa de datos'], a: 3,
        why: 'El mapa de datos de Purview escanea orígenes y registra metadatos, clasificaciones y linaje. El registro de actividad y ARM tratan operaciones sobre recursos de Azure.', d: 2 },
      { t: 'single', q: 'Una directiva con efecto Modify agrega una etiqueta faltante. Ya existían 200 recursos sin esa etiqueta antes de asignarla. ¿Cómo se ponen en cumplimiento?',
        o: ['Creando una tarea de corrección', 'Eliminando y recreando los recursos', 'Aplicando un bloqueo de solo lectura', 'Asignando el rol Colaborador a cada recurso'], a: 0,
        why: 'Las tareas de corrección aplican los efectos Modify o DeployIfNotExists a recursos existentes no conformes. No hace falta recrearlos.', d: 3 },
      { t: 'single', q: 'Se aplica un bloqueo Eliminar a un grupo de recursos. Luego alguien crea una VM dentro de ese grupo. ¿Puede eliminar la VM?',
        o: ['Sí, porque la VM se creó después del bloqueo', 'Sí, si tiene rol Propietario', 'No, porque la VM hereda el bloqueo del grupo de recursos', 'No, porque la VM queda en solo lectura'], a: 2,
        why: 'Los bloqueos se heredan a todos los recursos del ámbito, incluidos los creados después. Heredar un bloqueo Eliminar no la vuelve de solo lectura.', d: 2 },
      { t: 'multi', q: '¿En qué ámbitos se puede asignar una directiva de Azure Policy? Selecciona tres.',
        o: ['Grupo de administración', 'Cuenta de usuario de Microsoft Entra ID', 'Suscripción', 'Grupo de recursos', 'Grupo de acciones'], a: [0, 2, 3],
        why: 'Azure Policy se asigna a grupos de administración, suscripciones y grupos de recursos, y se hereda hacia abajo. Las cuentas de usuario se gobiernan con RBAC y los grupos de acciones son de Azure Monitor.', d: 1 },
      { t: 'multi', q: '¿Qué tipos de bloqueo de recursos existen en Azure? Selecciona dos.',
        o: ['NoWrite', 'Eliminar (CanNotDelete)', 'Auditar (Audit)', 'Solo lectura (ReadOnly)', 'Denegar todo (DenyAll)'], a: [1, 3],
        why: 'Azure solo tiene dos bloqueos: Eliminar y Solo lectura. Audit es un efecto de Azure Policy, y NoWrite y DenyAll no existen.', d: 1 },
      { t: 'multi', q: '¿Qué dos capacidades corresponden a Microsoft Purview? Selecciona dos.',
        o: ['Gobernar y catalogar datos en entornos locales, multinube y SaaS', 'Implementar máquinas virtuales con plantillas', 'Soluciones de riesgo y cumplimiento, como la protección de información sensible', 'Supervisar el uso de CPU de las VMs', 'Restringir las regiones donde se crean recursos'], a: [0, 2],
        why: 'Purview abarca gobernanza de datos y riesgo/cumplimiento. Desplegar VMs es de ARM, supervisar CPU es de Azure Monitor y restringir regiones es de Azure Policy.', d: 2 },
      { t: 'multi', q: '¿Qué dos afirmaciones describen correctamente Azure Policy? Selecciona dos.',
        o: ['Evalúa si los recursos cumplen las reglas de la organización', 'Asigna permisos a usuarios y grupos', 'Puede impedir la creación de recursos que no cumplan una regla', 'Solo puede aplicarse a recursos individuales', 'Reemplaza la necesidad de usar Microsoft Entra ID'], a: [0, 2],
        why: 'Azure Policy evalúa el cumplimiento y puede denegar recursos no conformes. Los permisos son de RBAC, se aplica a ámbitos amplios y no sustituye a Entra ID.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Un Propietario puede eliminar un recurso con bloqueo Eliminar sin quitar antes el bloqueo.', a: false },
          { text: 'Un bloqueo aplicado a un grupo de recursos se hereda a los recursos que contiene.', a: true },
          { text: 'Un bloqueo de solo lectura también impide eliminar el recurso.', a: true }
        ],
        why: 'Los bloqueos afectan a todos, incluido el Propietario, y se heredan. Solo lectura bloquea cambios y eliminación.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Una iniciativa agrupa varias definiciones de directiva.', a: true },
          { text: 'Azure Policy solo evalúa los recursos creados después de la asignación.', a: false },
          { text: 'Una directiva asignada a una suscripción se aplica a sus grupos de recursos.', a: true }
        ],
        why: 'Las iniciativas agrupan definiciones. Policy evalúa recursos nuevos y existentes, y la asignación se hereda a los ámbitos inferiores.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Microsoft Purview puede gobernar datos ubicados en centros de datos locales y en otras nubes.', a: true },
          { text: 'Microsoft Purview es la herramienta para asignar roles RBAC en Azure.', a: false },
          { text: 'Microsoft Purview incluye soluciones de riesgo y cumplimiento.', a: true }
        ],
        why: 'Purview cubre gobernanza de datos en local, multinube y SaaS, además de riesgo y cumplimiento. Los roles se asignan con RBAC.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'RBAC controla qué acciones puede realizar un usuario sobre un ámbito.', a: true },
          { text: 'Azure Policy controla qué propiedades pueden tener los recursos.', a: true },
          { text: 'Si RBAC permite a un usuario crear VMs, Azure Policy no puede impedir que cree una VM en una región prohibida.', a: false }
        ],
        why: 'Son capas complementarias: RBAC autoriza la acción y Azure Policy puede denegarla igualmente si el recurso incumple una regla, como la región.', d: 3 },
      { t: 'drop', q: 'Un bloqueo ___ permite leer y modificar un recurso, pero impide eliminarlo.',
        o: ['Solo lectura', 'Eliminar (CanNotDelete)', 'de auditoría', 'de denegación'], a: 1,
        why: 'El bloqueo Eliminar evita borrados pero permite cambios. Solo lectura impide cambios y borrados; auditoría y denegación son efectos de Azure Policy.', d: 1 },
      { t: 'drop', q: 'En Azure Policy, varias definiciones agrupadas para cumplir un objetivo, como una norma de seguridad, forman una ___.',
        o: ['asignación', 'función de rol', 'iniciativa', 'tarea de corrección'], a: 2,
        why: 'Una iniciativa agrupa definiciones. La asignación aplica una definición o iniciativa a un ámbito y la corrección arregla recursos existentes.', d: 1 },
      { t: 'drop', q: 'Para ver qué recursos no cumplen las reglas definidas por la organización se revisa el panel de cumplimiento de ___.',
        o: ['Azure Policy', 'Microsoft Entra ID', 'Azure Service Health', 'los bloqueos de recursos'], a: 0,
        why: 'Azure Policy muestra el estado de cumplimiento de cada recurso frente a las directivas asignadas.', d: 1 },
      { t: 'match', q: 'Relaciona cada necesidad con la herramienta de gobernanza adecuada.',
        pairs: [
          ['Impedir que se creen recursos fuera de Europa', 'Azure Policy'],
          ['Permitir a soporte reiniciar VMs pero no borrarlas', 'RBAC'],
          ['Evitar borrar por error el almacén de claves de producción', 'Bloqueo Eliminar'],
          ['Catalogar y clasificar datos en SQL local y AWS', 'Microsoft Purview']
        ],
        why: 'Policy rige propiedades, RBAC rige acciones de usuarios, los bloqueos protegen recursos concretos y Purview gobierna datos en todo el patrimonio.', d: 2 },
      { t: 'match', q: 'Relaciona cada efecto de Azure Policy con lo que hace.',
        pairs: [
          ['Deny', 'Impide crear o actualizar un recurso que no cumple'],
          ['Audit', 'Registra el incumplimiento sin bloquear'],
          ['Modify', 'Agrega o cambia propiedades, como etiquetas'],
          ['DeployIfNotExists', 'Despliega un recurso relacionado si falta']
        ],
        why: 'Deny bloquea, Audit solo informa, Modify ajusta propiedades y DeployIfNotExists completa la configuración desplegando lo que falta.', d: 3 }
    ] },

  // ───────────────────────────── w3l3 ─────────────────────────────
  { id: 'w3l3', title: 'Herramientas para administrar e implementar', minutes: 7,
    goal: 'Elegir entre portal, Cloud Shell, CLI, PowerShell, Azure Arc, plantillas ARM y Bicep según el escenario.',
    lesson: [
      { type: 'text', title: 'Muchas puertas, una sola recepción',
        body: 'Puedes administrar Azure con clics, con comandos o con código. Pero todas las vías terminan en el mismo sitio: **Azure Resource Manager (ARM)**, la capa de implementación y administración que **autentica, autoriza** y ejecuta cada solicitud.' },
      { type: 'analogy',
        body: 'ARM es la **ventanilla única de un ayuntamiento**. Puedes llegar en persona (portal), por teléfono (CLI), por correo (PowerShell) o enviando un formulario completo (plantilla): la ventanilla verifica quién eres, si tienes permiso y aplica las mismas reglas a todos.' },
      { type: 'cards', title: 'Herramientas de administración',
        items: [
          { title: 'Azure Portal', body: 'Interfaz **web gráfica** para crear, administrar y supervisar recursos, con paneles personalizables. Ideal para explorar y tareas puntuales.' },
          { title: 'Azure Cloud Shell', body: 'Shell en el **navegador**, ya **autenticado**, con **Bash** o **PowerShell** y herramientas preinstaladas. Nada que instalar.' },
          { title: 'CLI de Azure', body: 'Comandos `az` (por ejemplo `az vm create`). Multiplataforma, muy usada en scripts Bash.' },
          { title: 'Azure PowerShell', body: 'Módulo Az con cmdlets verbo-sustantivo (por ejemplo `New-AzVM`). Multiplataforma con PowerShell 7.' },
          { title: 'Azure Arc', body: 'Lleva la administración de Azure a **servidores, Kubernetes y datos fuera de Azure**: local u otras nubes.' }
        ] },
      { type: 'compare', title: 'CLI de Azure vs Azure PowerShell',
        head: ['', 'CLI de Azure', 'Azure PowerShell'],
        rows: [
          ['Sintaxis', '`az grupo comando`', 'Cmdlets `Verbo-AzSustantivo`'],
          ['Ejemplo', '`az group create`', '`New-AzResourceGroup`'],
          ['Plataformas', 'Windows, macOS, Linux', 'Windows, macOS, Linux'],
          ['En Cloud Shell', 'Sí', 'Sí'],
          ['Capacidad', 'Equivalente en lo esencial', 'Equivalente en lo esencial']
        ] },
      { type: 'text', title: 'Azure Arc en una frase',
        body: 'Arc **proyecta** recursos externos (servidores locales o en AWS/GCP, clústeres Kubernetes, SQL Server y servicios de datos) dentro de **Azure Resource Manager**. Así puedes aplicarles **etiquetas, RBAC, Azure Policy, Azure Monitor y Defender for Cloud** como si estuvieran en Azure.' },
      { type: 'trap',
        body: 'Azure Arc **no migra** servidores a Azure: siguen donde están; solo se administran desde Azure. Y Cloud Shell **no es otro lenguaje**: es un lugar (el navegador) donde ejecutas CLI de Azure o Azure PowerShell.' },
      { type: 'flip', title: 'Infraestructura como código',
        items: [
          { front: 'Declarativa', back: 'Describes el **estado final** deseado (“quiero una VM así”); la plataforma decide cómo llegar. Plantillas ARM y Bicep.' },
          { front: 'Imperativa', back: 'Escribes los **pasos** en orden (“crea red, luego crea VM”). Scripts de CLI o PowerShell.' },
          { front: 'Plantilla ARM', back: 'Archivo **JSON** declarativo que describe recursos. Validación previa, orquestación de dependencias, módulos y seguimiento de implementaciones.' },
          { front: 'Idempotente', back: 'Implementar la misma plantilla varias veces da **el mismo resultado**, sin duplicar recursos.' },
          { front: 'Bicep', back: 'Lenguaje declarativo con sintaxis más **concisa** que JSON. Se **transpila** a plantilla ARM y admite módulos.' }
        ] },
      { type: 'order', title: 'Ordena una implementación con Bicep',
        items: [
          'Escribes el archivo Bicep con el estado deseado',
          'Bicep se transpila a una plantilla ARM en JSON',
          'Envías la implementación con CLI, PowerShell o el portal',
          'Resource Manager autentica y autoriza la solicitud',
          'Resource Manager crea los recursos respetando dependencias'
        ] },
      { type: 'check', q: 'Un administrador quiere aplicar Azure Policy y etiquetas a 50 servidores Linux de su centro de datos sin moverlos. ¿Qué usa?',
        o: ['Azure Migrate', 'Azure Arc', 'Azure Cloud Shell'], a: 1,
        why: 'Azure Arc proyecta los servidores locales en ARM para gobernarlos desde Azure sin migrarlos. Migrate sirve para trasladarlos a Azure.' },
      { type: 'keypoints', items: [
        'Todas las herramientas pasan por Azure Resource Manager.',
        'Cloud Shell: Bash o PowerShell en el navegador, autenticado y sin instalar nada.',
        'CLI = `az ...`; PowerShell = cmdlets `Verbo-Az...`; ambas multiplataforma.',
        'Azure Arc administra servidores, Kubernetes y datos fuera de Azure, sin migrarlos.',
        'Plantillas ARM (JSON) y Bicep: declarativas e idempotentes.'
      ] }
    ],
    questions: [
      { t: 'single', q: 'Un administrador está en un equipo prestado sin herramientas instaladas y necesita ejecutar comandos de la CLI de Azure de inmediato. ¿Qué debe usar?',
        o: ['Azure Arc', 'Una plantilla ARM', 'Azure Cloud Shell', 'Azure Advisor'], a: 2,
        why: 'Cloud Shell se abre en el navegador, ya autenticado, con la CLI de Azure y Azure PowerShell preinstaladas. Arc gestiona recursos externos y una plantilla describe infraestructura, no es una consola.', d: 1 },
      { t: 'single', q: 'Una empresa tiene servidores Windows en su centro de datos y clústeres Kubernetes en otra nube. Quiere gobernarlos con Azure Policy y etiquetas desde Azure. ¿Qué servicio necesita?',
        o: ['Azure Arc', 'Azure Cloud Shell', 'Bicep', 'Microsoft Purview'], a: 0,
        why: 'Azure Arc extiende la administración de Azure a servidores, Kubernetes y servicios de datos fuera de Azure. Purview gobierna datos, no la configuración de servidores.', d: 1 },
      { t: 'single', q: 'Las solicitudes hechas desde el portal, la CLI, PowerShell o la API REST, ¿por qué servicio pasan antes de crear o modificar recursos?',
        o: ['Azure Monitor', 'Microsoft Entra ID Connect', 'Azure Arc', 'Azure Resource Manager'], a: 3,
        why: 'Azure Resource Manager es la capa de implementación y administración: recibe, autentica y autoriza todas las solicitudes, sin importar la herramienta usada.', d: 1 },
      { t: 'single', q: '¿Qué significa que una plantilla ARM sea idempotente?',
        o: ['Que solo puede ejecutarse una vez', 'Que implementarla varias veces produce el mismo estado final', 'Que se ejecuta paso a paso en el orden escrito', 'Que debe escribirse en PowerShell'], a: 1,
        why: 'Idempotente significa que repetir la implementación da el mismo resultado sin duplicar recursos. Ejecutar pasos en orden es propio del enfoque imperativo.', d: 2 },
      { t: 'single', q: '¿En qué formato se escriben las plantillas de Azure Resource Manager?',
        o: ['YAML', 'XML', 'JSON', 'Python'], a: 2,
        why: 'Las plantillas ARM son archivos JSON. Bicep ofrece una sintaxis alternativa más concisa que se convierte a ese JSON.', d: 1 },
      { t: 'single', q: '¿Qué describe mejor a Bicep?',
        o: ['Un lenguaje declarativo que se transpila a plantillas ARM', 'Un shell en el navegador para administrar Azure', 'Un agente para administrar servidores fuera de Azure', 'Un servicio de supervisión de aplicaciones'], a: 0,
        why: 'Bicep es un lenguaje específico de dominio para IaC en Azure, declarativo y con módulos, que se convierte a JSON de ARM. Cloud Shell es el shell y Arc el agente híbrido.', d: 1 },
      { t: 'single', q: 'Un nuevo empleado sin experiencia en scripting necesita explorar los recursos de una suscripción y crear un panel visual personalizado. ¿Qué herramienta es más adecuada?',
        o: ['CLI de Azure', 'Azure PowerShell', 'Plantillas ARM', 'Azure Portal'], a: 3,
        why: 'El portal es la interfaz gráfica web, con paneles personalizables, ideal para explorar sin escribir comandos. Las demás opciones requieren comandos o código.', d: 1 },
      { t: 'single', q: 'Un script contiene la línea `New-AzResourceGroup -Name RG-Web -Location westeurope`. ¿Qué herramienta se está usando?',
        o: ['CLI de Azure', 'Azure PowerShell', 'Bicep', 'Azure Arc'], a: 1,
        why: 'Los cmdlets con formato Verbo-AzSustantivo, como New-AzResourceGroup, pertenecen al módulo Az de Azure PowerShell. La CLI usa comandos az.', d: 1 },
      { t: 'single', q: 'Un desarrollador ejecuta `az vm list --output table` desde Bash en su Mac. ¿Qué herramienta usa?',
        o: ['Azure PowerShell', 'Azure Portal', 'CLI de Azure', 'Azure Resource Graph Explorer'], a: 2,
        why: 'Los comandos que empiezan por az son de la CLI de Azure, multiplataforma. Azure PowerShell usa cmdlets como Get-AzVM.', d: 1 },
      { t: 'single', q: '¿Qué caracteriza un enfoque declarativo de infraestructura como código?',
        o: ['Se define el estado final deseado y la plataforma determina cómo alcanzarlo', 'Se escribe cada paso en el orden exacto en que debe ejecutarse', 'Solo puede usarse desde el portal', 'No permite volver a implementar el mismo archivo'], a: 0,
        why: 'Lo declarativo describe el “qué” (estado final), no el “cómo”. Escribir pasos en orden es imperativo, y las plantillas declarativas se pueden reimplementar.', d: 2 },
      { t: 'single', q: 'Después de conectar un servidor local con Azure Arc, ¿qué ocurre con él?',
        o: ['Se migra automáticamente a una VM de Azure', 'Se apaga el servidor local y se usa uno en Azure', 'Aparece como recurso en Azure Resource Manager y puede gestionarse con RBAC, etiquetas y Azure Policy', 'Solo puede administrarse con Azure Cloud Shell'], a: 2,
        why: 'Arc proyecta el servidor en ARM sin moverlo, de modo que puedes aplicarle herramientas de Azure como RBAC, etiquetas, Azure Policy o Azure Monitor.', d: 2 },
      { t: 'single', q: 'Una plantilla define una red virtual, una VM que depende de ella y una cuenta de almacenamiento independiente. ¿Qué beneficio de ARM se aprecia al implementarla?',
        o: ['La plantilla debe dividirse en tres implementaciones manuales', 'ARM orquesta el orden según dependencias y crea en paralelo lo independiente', 'ARM crea los recursos en orden alfabético', 'Solo se crea el primer recurso definido'], a: 1,
        why: 'Resource Manager orquesta la implementación: respeta dependencias (la red antes que la VM) y despliega en paralelo lo que no depende de nada.', d: 3 },
      { t: 'single', q: 'Un equipo necesita crear entornos de desarrollo, pruebas y producción idénticos, de forma repetible y versionada en Git. ¿Qué enfoque es el más adecuado?',
        o: ['Crearlos manualmente en el portal siguiendo un documento', 'Usar Azure Advisor para replicarlos', 'Usar Azure Service Health', 'Definirlos como código con Bicep o plantillas ARM'], a: 3,
        why: 'La infraestructura como código con Bicep o plantillas ARM produce entornos consistentes, repetibles y versionables. Hacerlo a mano introduce errores, y Advisor y Service Health no despliegan.', d: 1 },
      { t: 'multi', q: '¿Qué entornos de línea de comandos puedes elegir en Azure Cloud Shell? Selecciona dos.',
        o: ['Bash', 'Símbolo del sistema (cmd.exe)', 'PowerShell', 'Consola de Python', 'Terminal de AWS CloudShell'], a: [0, 2],
        why: 'Cloud Shell ofrece Bash y PowerShell, ambos con la CLI de Azure y Azure PowerShell disponibles. No ofrece cmd.exe como opción de shell.', d: 1 },
      { t: 'multi', q: '¿Qué puede administrarse con Azure Arc? Selecciona tres.',
        o: ['Servidores físicos o virtuales en un centro de datos local', 'Clústeres de Kubernetes en otra nube', 'Licencias de Microsoft 365 de los usuarios', 'SQL Server ejecutándose fuera de Azure', 'Cuentas de facturación de AWS'], a: [0, 1, 3],
        why: 'Arc cubre servidores, Kubernetes y servicios de datos como SQL Server fuera de Azure. No administra licencias de Microsoft 365 ni la facturación de otras nubes.', d: 2 },
      { t: 'multi', q: '¿Qué dos beneficios aporta Azure Resource Manager? Selecciona dos.',
        o: ['Administrar un conjunto de recursos como una unidad, por ejemplo con grupos de recursos', 'Dar acceso físico a los centros de datos de Microsoft', 'Aplicar RBAC, etiquetas y bloqueos de forma coherente desde cualquier herramienta', 'Eliminar la necesidad de autenticarse', 'Reducir automáticamente el precio de las VMs'], a: [0, 2],
        why: 'ARM permite gestionar recursos en grupo y aplica control de acceso, etiquetas y bloqueos igual desde portal, CLI, PowerShell o plantillas. Sigue exigiendo autenticación y no fija precios.', d: 2 },
      { t: 'multi', q: '¿Qué dos características ofrecen las plantillas ARM? Selecciona dos.',
        o: ['Archivos modulares que pueden dividirse y reutilizarse', 'Definición imperativa paso a paso', 'Validación de la plantilla antes de la implementación', 'Uso exclusivo desde el portal', 'Creación de recursos duplicados en cada ejecución'], a: [0, 2],
        why: 'Las plantillas ARM son modulares y se validan antes de desplegar. Son declarativas, se usan desde cualquier herramienta y son idempotentes, sin duplicar recursos.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'La CLI de Azure y Azure PowerShell funcionan en Windows, macOS y Linux.', a: true },
          { text: 'Para usar la CLI de Azure es obligatorio abrir Azure Cloud Shell.', a: false },
          { text: 'Las tareas de administración del portal suelen poder automatizarse con la CLI o PowerShell.', a: true }
        ],
        why: 'Ambas herramientas son multiplataforma y pueden instalarse localmente; Cloud Shell es solo una opción. Al pasar todo por ARM, lo del portal suele poder hacerse por comandos.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Azure Arc permite aplicar Azure Policy a servidores locales.', a: true },
          { text: 'Azure Arc migra automáticamente los servidores locales a Azure.', a: false },
          { text: 'Azure Arc puede administrar servidores que se ejecutan en otro proveedor de nube.', a: true }
        ],
        why: 'Arc gobierna recursos fuera de Azure, en local o en otras nubes, sin moverlos. Para migrar se usan otras herramientas, como Azure Migrate.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Bicep es un lenguaje declarativo.', a: true },
          { text: 'Implementar dos veces la misma plantilla ARM sin cambios crea recursos duplicados.', a: false },
          { text: 'Las plantillas ARM pueden guardarse y versionarse en un repositorio de código.', a: true }
        ],
        why: 'Bicep y ARM son declarativos e idempotentes: repetir la implementación no duplica recursos. Como son archivos de texto, se versionan en Git.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Azure Cloud Shell requiere instalar la CLI de Azure en tu equipo.', a: false },
          { text: 'Azure Cloud Shell se abre autenticado con tu cuenta de Azure.', a: true },
          { text: 'En Azure Cloud Shell están disponibles la CLI de Azure y Azure PowerShell.', a: true }
        ],
        why: 'Cloud Shell se ejecuta en el navegador, ya autenticado y con las herramientas preinstaladas; no hay que instalar nada localmente.', d: 1 },
      { t: 'drop', q: '___ es la capa de implementación y administración de Azure que recibe, autentica y autoriza todas las solicitudes.',
        o: ['Azure Arc', 'Azure Resource Manager', 'Azure Cloud Shell', 'Azure Monitor'], a: 1,
        why: 'Azure Resource Manager es el punto común por el que pasan portal, CLI, PowerShell, API REST y plantillas.', d: 1 },
      { t: 'drop', q: 'Un script que ejecuta comandos en secuencia, “crea la red” y luego “crea la VM”, sigue un enfoque ___.',
        o: ['declarativo', 'idempotente', 'imperativo'], a: 2,
        why: 'Indicar los pasos y su orden es imperativo. En el declarativo describes el estado final y la plataforma decide los pasos.', d: 1 },
      { t: 'drop', q: 'Antes de implementarse, un archivo Bicep se transpila a ___.',
        o: ['una plantilla ARM en JSON', 'un script de PowerShell', 'un manifiesto YAML de Kubernetes', 'comandos de la CLI de Azure'], a: 0,
        why: 'Bicep se convierte en una plantilla ARM en JSON, que es lo que Resource Manager implementa.', d: 2 },
      { t: 'match', q: 'Relaciona cada herramienta con su descripción.',
        pairs: [
          ['Azure Portal', 'Interfaz web gráfica con paneles personalizables'],
          ['Azure Cloud Shell', 'Bash o PowerShell en el navegador, ya autenticado'],
          ['CLI de Azure', 'Comandos que empiezan por az'],
          ['Azure PowerShell', 'Cmdlets como New-AzVM']
        ],
        why: 'El portal es gráfico, Cloud Shell es una consola en el navegador, la CLI usa comandos az y PowerShell usa cmdlets Verbo-Az.', d: 1 },
      { t: 'match', q: 'Relaciona cada necesidad con la opción más adecuada.',
        pairs: [
          ['Administrar desde Azure un clúster Kubernetes en otra nube', 'Azure Arc'],
          ['Describir infraestructura en un archivo JSON declarativo', 'Plantilla ARM'],
          ['Escribir IaC declarativa con sintaxis más concisa y módulos', 'Bicep'],
          ['Ejecutar comandos sin instalar nada en el equipo', 'Azure Cloud Shell']
        ],
        why: 'Arc extiende Azure a recursos externos, ARM usa JSON, Bicep simplifica esa sintaxis y Cloud Shell funciona en el navegador.', d: 2 }
    ] },

  // ───────────────────────────── w3l4 ─────────────────────────────
  { id: 'w3l4', title: 'Supervisión', minutes: 7,
    goal: 'Saber cuándo usar Azure Advisor, Azure Service Health, Azure Monitor, Log Analytics, alertas y Application Insights.',
    lesson: [
      { type: 'text', title: 'Tres preguntas, tres servicios',
        body: '¿**Qué puedo mejorar**? → **Azure Advisor**. ¿**Azure está fallando** y me afecta? → **Azure Service Health**. ¿**Cómo se comportan** mis recursos y apps? → **Azure Monitor**. Casi todas las preguntas de supervisión del examen se resuelven identificando cuál de las tres se está haciendo.' },
      { type: 'analogy',
        body: 'Piensa en tu **auto**. **Azure Monitor** es el tablero: velocidad, temperatura, combustible (métricas) y la caja negra (registros). **Azure Advisor** es el mecánico que te dice “cambia las llantas y ahorrarás gasolina”. **Azure Service Health** es la radio de tráfico que avisa “la autopista de tu ruta está cortada”.' },
      { type: 'cards', title: 'Azure Advisor: 5 categorías',
        items: [
          { title: 'Confiabilidad', body: 'Mejorar la continuidad: zonas de disponibilidad, copias de seguridad, redundancia.' },
          { title: 'Seguridad', body: 'Detectar amenazas y vulnerabilidades (integrado con Microsoft Defender for Cloud).' },
          { title: 'Rendimiento', body: 'Mejorar la velocidad y capacidad de respuesta de tus aplicaciones.' },
          { title: 'Excelencia operativa', body: 'Procesos, flujo de trabajo y buenas prácticas de implementación y administración.' },
          { title: 'Costo', body: 'Ahorrar: por ejemplo, redimensionar o apagar VMs infrautilizadas o comprar reservas.' }
        ] },
      { type: 'compare', title: 'Azure Service Health: tres capas',
        head: ['', 'Azure Status', 'Service Health', 'Resource Health'],
        rows: [
          ['Alcance', 'Todos los servicios y regiones', 'Tus servicios y tus regiones', 'Tus recursos individuales'],
          ['Personalizado', 'No, página pública', 'Sí', 'Sí'],
          ['Ejemplo', 'Incidencia global de almacenamiento', 'Mantenimiento planificado en tu región', '¿Mi VM no responde por culpa de Azure?']
        ] },
      { type: 'trap',
        body: 'No confundas: **Advisor** recomienda (no detecta caídas); **Service Health** informa de problemas **de la plataforma Azure** que te afectan; **Monitor** mide **tus** recursos y aplicaciones. Si la pregunta habla de “mantenimiento planificado” o “incidente de Azure en mi región”, es **Service Health**, no Monitor.' },
      { type: 'cards', title: 'Azure Monitor por dentro',
        items: [
          { title: 'Métricas', body: 'Valores **numéricos** a intervalos regulares, casi en tiempo real: % de CPU, solicitudes por segundo.' },
          { title: 'Registros', body: 'Eventos y datos detallados con marca de tiempo, almacenados en un **área de trabajo de Log Analytics**.' },
          { title: 'Log Analytics', body: 'Herramienta del portal para escribir y ejecutar consultas **KQL** (Kusto Query Language) sobre los registros.' },
          { title: 'Alertas', body: 'Se disparan por **métricas**, **búsquedas de registros** o el **registro de actividad** (por ejemplo, alguien eliminó una VM).' },
          { title: 'Grupos de acciones', body: 'Definen **a quién avisar y qué ejecutar**: correo, SMS, notificación push, llamada, webhook, Logic App, Azure Function, runbook.' },
          { title: 'Application Insights', body: 'Supervisión del rendimiento de aplicaciones (**APM**): tiempos de respuesta, errores, dependencias. También para apps **locales o en otras nubes**.' }
        ] },
      { type: 'trap',
        body: 'Application Insights **no** se limita a aplicaciones hospedadas en Azure: puede supervisar apps en local o en otra nube. Y Azure Monitor también recopila datos de máquinas fuera de Azure (por ejemplo, con Azure Arc y el agente de Azure Monitor).' },
      { type: 'sort', title: '¿Quién responde?', buckets: ['Azure Advisor', 'Service Health', 'Azure Monitor'],
        items: [
          { text: '¿Cómo ahorro en VMs infrautilizadas?', bucket: 0 },
          { text: '¿Habrá mantenimiento en mi región la próxima semana?', bucket: 1 },
          { text: '¿Cuál fue el uso de CPU de mi VM ayer?', bucket: 2 },
          { text: '¿Debo habilitar zonas de disponibilidad para mejorar la confiabilidad?', bucket: 0 },
          { text: '¿Hay una incidencia de Azure que afecta a mis servicios ahora?', bucket: 1 },
          { text: 'Avísame si el disco supera el 90 % de uso', bucket: 2 }
        ] },
      { type: 'check', q: 'Una VM concreta dejó de responder y quieres saber si la causa es un problema de la plataforma Azure en ese recurso. ¿Dónde miras?',
        o: ['Azure Status', 'Resource Health', 'Azure Advisor'], a: 1,
        why: 'Resource Health informa del estado de tus recursos individuales y si una incidencia de Azure los afecta. Azure Status es global y Advisor solo recomienda.' },
      { type: 'keypoints', items: [
        'Advisor recomienda: confiabilidad, seguridad, rendimiento, excelencia operativa y costo.',
        'Azure Status = global y público; Service Health = tus servicios y regiones; Resource Health = tus recursos.',
        'Azure Monitor recopila métricas y registros; Log Analytics consulta registros con KQL.',
        'Alertas: métricas, registros o registro de actividad; los grupos de acciones definen la respuesta.',
        'Application Insights = APM, también para apps fuera de Azure.'
      ] }
    ],
    questions: [
      { t: 'single', q: 'Una empresa quiere recibir recomendaciones personalizadas para reducir el gasto en VMs con poco uso, sin instalar nada. ¿Qué servicio debe consultar?',
        o: ['Azure Service Health', 'Azure Advisor', 'Application Insights', 'Azure Status'], a: 1,
        why: 'Azure Advisor analiza tu configuración y uso y da recomendaciones, incluida la categoría de costo. Service Health y Azure Status informan de incidencias, y Application Insights supervisa apps.', d: 1 },
      { t: 'single', q: 'Un administrador quiere saber si una incidencia en curso de Azure afecta a los servicios que su empresa usa en la región Este de EE. UU., con información personalizada para su suscripción. ¿Qué usa?',
        o: ['Azure Service Health', 'Azure Status', 'Azure Advisor', 'Log Analytics'], a: 0,
        why: 'Service Health muestra incidencias, mantenimientos y avisos que afectan a tus servicios y regiones. Azure Status es una vista pública global, no personalizada.', d: 1 },
      { t: 'single', q: 'Un consultor sin acceso a la suscripción del cliente quiere comprobar si hay una incidencia generalizada de Azure en todas las regiones. ¿Qué consulta?',
        o: ['Resource Health', 'Azure Advisor', 'Application Insights', 'La página de Azure Status'], a: 3,
        why: 'Azure Status es pública y muestra el estado global de los servicios de Azure sin necesidad de iniciar sesión. Resource Health requiere acceso a los recursos.', d: 2 },
      { t: 'single', q: 'Una VM de producción aparece como “No disponible” y el equipo quiere saber si la causa es un evento de la plataforma Azure que afecta a esa VM concreta. ¿Qué herramienta da esa información?',
        o: ['Azure Advisor', 'Azure Status', 'Resource Health', 'Microsoft Cost Management'], a: 2,
        why: 'Resource Health muestra el estado actual e histórico de cada recurso y si un problema de Azure lo afecta. Azure Status es global y Advisor recomienda mejoras.', d: 2 },
      { t: 'single', q: '¿Qué lenguaje se usa para consultar los registros en Log Analytics?',
        o: ['T-SQL', 'Bicep', 'Kusto Query Language (KQL)', 'JSON'], a: 2,
        why: 'Log Analytics usa KQL para consultar los registros de un área de trabajo. Bicep y JSON describen infraestructura y T-SQL es de SQL Server.', d: 1 },
      { t: 'single', q: 'Un equipo de desarrollo quiere medir los tiempos de respuesta de su web, las tasas de error y las llamadas a dependencias como bases de datos. ¿Qué característica de Azure Monitor debe usar?',
        o: ['Application Insights', 'Azure Service Health', 'Azure Advisor', 'Resource Health'], a: 0,
        why: 'Application Insights es la funcionalidad de APM de Azure Monitor: rendimiento, errores, dependencias y uso de aplicaciones. Las demás no instrumentan aplicaciones.', d: 1 },
      { t: 'single', q: 'Una aplicación web se ejecuta en servidores del centro de datos local de la empresa. ¿Puede supervisarse con Application Insights?',
        o: ['No, solo funciona con Azure App Service', 'Sí, Application Insights puede supervisar aplicaciones en local o en otras nubes', 'Solo si se migra antes a una VM de Azure', 'Solo mediante Azure Service Health'], a: 1,
        why: 'Application Insights supervisa aplicaciones donde sea que se ejecuten: Azure, local u otras nubes, siempre que puedan enviar telemetría.', d: 2 },
      { t: 'single', q: 'En Azure Monitor, ¿para qué sirve un grupo de acciones?',
        o: ['Para agrupar recursos que comparten el mismo ciclo de vida', 'Para organizar suscripciones jerárquicamente', 'Para agrupar definiciones de Azure Policy', 'Para definir notificaciones y acciones que se ejecutan cuando se dispara una alerta'], a: 3,
        why: 'Un grupo de acciones indica a quién notificar (correo, SMS…) y qué ejecutar (webhook, Logic App, runbook). Las otras opciones describen grupos de recursos, grupos de administración e iniciativas.', d: 2 },
      { t: 'single', q: 'Se quiere recibir un aviso cuando el uso de CPU de una VM supere el 85 % durante 10 minutos. ¿Qué configuras?',
        o: ['Una alerta de métrica en Azure Monitor', 'Una recomendación de Azure Advisor', 'Una alerta de presupuesto', 'Un bloqueo de solo lectura'], a: 0,
        why: 'El % de CPU es una métrica numérica, por lo que corresponde una alerta de métrica. Las alertas de presupuesto tratan gasto y Advisor no envía alertas de umbral.', d: 1 },
      { t: 'single', q: 'Seguridad quiere ser notificada cada vez que alguien elimine una máquina virtual en la suscripción. ¿Qué tipo de alerta de Azure Monitor es la más directa?',
        o: ['Alerta de métrica de CPU', 'Alerta de presupuesto', 'Alerta del registro de actividad', 'Alerta de Azure Status'], a: 2,
        why: 'El registro de actividad recoge las operaciones de administración, como eliminar una VM, y puede disparar alertas. Las métricas miden rendimiento, no operaciones.', d: 2 },
      { t: 'single', q: '¿Qué diferencia mejor las métricas de los registros en Azure Monitor?',
        o: ['Las métricas solo existen para aplicaciones locales', 'Las métricas son valores numéricos a intervalos regulares; los registros son eventos y datos detallados que se consultan con KQL', 'Los registros son siempre en tiempo real y las métricas se guardan solo un día', 'No hay diferencia: son el mismo dato'], a: 1,
        why: 'Las métricas son series numéricas ligeras, casi en tiempo real. Los registros contienen eventos y datos ricos guardados en Log Analytics y se consultan con KQL.', d: 2 },
      { t: 'single', q: 'Azure Advisor recomienda configurar copias de seguridad y distribuir VMs en zonas de disponibilidad. ¿A qué categoría pertenecen estas recomendaciones?',
        o: ['Costo', 'Rendimiento', 'Excelencia operativa', 'Confiabilidad'], a: 3,
        why: 'Las recomendaciones de confiabilidad buscan garantizar la continuidad del negocio: redundancia, zonas de disponibilidad y copias de seguridad.', d: 2 },
      { t: 'single', q: 'Un equipo quiere enterarse con antelación del mantenimiento planificado que Azure hará en los servicios que usa y configurar alertas para ello. ¿Qué debe usar?',
        o: ['Azure Advisor', 'Azure Service Health', 'Log Analytics', 'Microsoft Purview'], a: 1,
        why: 'Service Health informa de incidencias, mantenimiento planificado y avisos de salud y seguridad para tus servicios, y permite crear alertas de estado de los servicios.', d: 1 },
      { t: 'multi', q: '¿Cuáles son categorías de recomendaciones de Azure Advisor? Selecciona tres.',
        o: ['Confiabilidad', 'Gobernanza de identidades', 'Seguridad', 'Costo', 'Cumplimiento legal'], a: [0, 2, 3],
        why: 'Advisor tiene cinco categorías: confiabilidad, seguridad, rendimiento, excelencia operativa y costo. Gobernanza de identidades y cumplimiento legal no son categorías de Advisor.', d: 1 },
      { t: 'multi', q: '¿Cuáles son los dos tipos fundamentales de datos que recopila Azure Monitor? Selecciona dos.',
        o: ['Facturas', 'Métricas', 'Plantillas ARM', 'Registros', 'Definiciones de directiva'], a: [1, 3],
        why: 'Azure Monitor se basa en métricas y registros. Las facturas son de Cost Management, las plantillas de ARM y las directivas de Azure Policy.', d: 1 },
      { t: 'multi', q: '¿Qué orígenes de señal pueden disparar una alerta de Azure Monitor? Selecciona tres.',
        o: ['Métricas', 'Búsquedas en registros', 'La calculadora de precios', 'El registro de actividad', 'Las etiquetas de los recursos'], a: [0, 1, 3],
        why: 'Las alertas de Azure Monitor pueden basarse en métricas, consultas de registros y el registro de actividad. La calculadora y las etiquetas no generan señales de alerta.', d: 2 },
      { t: 'multi', q: '¿Qué dos acciones puede realizar un grupo de acciones cuando se dispara una alerta? Selecciona dos.',
        o: ['Enviar un correo electrónico o un SMS', 'Reembolsar el costo del incidente', 'Ejecutar una Logic App o una Azure Function', 'Crear una iniciativa de Azure Policy', 'Cambiar la región del recurso'], a: [0, 2],
        why: 'Los grupos de acciones notifican (correo, SMS, push, voz) y automatizan (webhook, Logic App, Azure Function, runbook). No crean directivas ni mueven recursos.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Azure Status muestra el estado global de los servicios de Azure en todas las regiones.', a: true },
          { text: 'Service Health muestra información relevante para los servicios y regiones que usas.', a: true },
          { text: 'Resource Health muestra el estado de todos los servicios de Azure a nivel mundial.', a: false }
        ],
        why: 'Azure Status es la vista global, Service Health se centra en tus servicios y regiones, y Resource Health en tus recursos individuales.', d: 1 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Azure Advisor implementa automáticamente todas sus recomendaciones.', a: false },
          { text: 'Azure Advisor puede recomendar redimensionar o apagar VMs infrautilizadas.', a: true },
          { text: 'Azure Advisor ofrece recomendaciones de seguridad.', a: true }
        ],
        why: 'Advisor recomienda y tú decides si aplicar los cambios; algunas recomendaciones ofrecen corrección rápida, pero no se aplican solas. Incluye costo y seguridad, entre otras categorías.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Log Analytics permite consultar registros con KQL.', a: true },
          { text: 'Azure Monitor solo puede recopilar datos de recursos hospedados en Azure.', a: false },
          { text: 'Una alerta puede usar un grupo de acciones para enviar un SMS.', a: true }
        ],
        why: 'Log Analytics usa KQL. Azure Monitor también recopila datos de entornos locales y otras nubes (por ejemplo con Azure Arc), y los grupos de acciones pueden enviar SMS.', d: 2 },
      { t: 'yn', q: 'Para cada afirmación, selecciona Sí o No.',
        s: [
          { text: 'Application Insights es una característica de Azure Monitor.', a: true },
          { text: 'Application Insights solo puede supervisar aplicaciones de Azure App Service.', a: false },
          { text: 'Application Insights puede detectar tiempos de respuesta lentos y excepciones.', a: true }
        ],
        why: 'Application Insights forma parte de Azure Monitor, supervisa apps en Azure, en local u otras nubes, y mide rendimiento, errores y dependencias.', d: 1 },
      { t: 'drop', q: 'Para consultar con KQL los registros almacenados en un área de trabajo se usa ___.',
        o: ['Azure Advisor', 'Log Analytics', 'Azure Status', 'Resource Health'], a: 1,
        why: 'Log Analytics es la herramienta de Azure Monitor para escribir y ejecutar consultas KQL sobre registros.', d: 1 },
      { t: 'drop', q: 'El servicio que avisa del mantenimiento planificado que afectará a tus recursos en tus regiones es ___.',
        o: ['Azure Status', 'Application Insights', 'Azure Advisor', 'Azure Service Health'], a: 3,
        why: 'Service Health notifica incidencias y mantenimiento planificado personalizados. Azure Status es genérico y no se adapta a tu suscripción.', d: 1 },
      { t: 'drop', q: 'Un ___ define a quién notificar y qué acciones ejecutar cuando se dispara una alerta.',
        o: ['grupo de acciones', 'grupo de recursos', 'grupo de administración'], a: 0,
        why: 'Los grupos de acciones contienen notificaciones y acciones automatizadas. Los grupos de recursos y de administración organizan recursos y suscripciones.', d: 1 },
      { t: 'match', q: 'Relaciona cada pregunta con el servicio que la responde.',
        pairs: [
          ['¿Cómo puedo ahorrar o mejorar mi seguridad?', 'Azure Advisor'],
          ['¿Hay un problema de Azure en mis regiones?', 'Azure Service Health'],
          ['¿Cuál fue el % de CPU de mi VM en la última hora?', 'Métricas de Azure Monitor'],
          ['¿Por qué mi web tarda en responder a los usuarios?', 'Application Insights']
        ],
        why: 'Advisor recomienda, Service Health informa de incidencias de Azure, las métricas miden recursos y Application Insights analiza el rendimiento de la aplicación.', d: 2 },
      { t: 'match', q: 'Relaciona cada componente de Azure Service Health con su alcance.',
        pairs: [
          ['Azure Status', 'Estado global de todos los servicios y regiones'],
          ['Service Health', 'Servicios y regiones que usa tu organización'],
          ['Resource Health', 'Cada uno de tus recursos individuales']
        ],
        why: 'De lo más general a lo más específico: Azure Status (todo Azure), Service Health (lo que tú usas) y Resource Health (un recurso concreto).', d: 2 }
    ] }
  ]
});
